import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { FiSearch, FiFilter, FiAward, FiFileText, FiUser, FiFolder, FiX, FiDownload } from 'react-icons/fi';
import { searchAPI, categoriesAPI, authorsAPI } from '../services/api';
import { toast } from 'react-toastify';
import Loading from '../components/Loading';
import Pagination from '../components/Pagination';
import './Search.css';

const Search = () => {
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState({ patents: [], documents: [], authors: [] });
  const [categories, setCategories] = useState([]);
  const [activeTab, setActiveTab] = useState('all');

  const [filters, setFilters] = useState({
    query: '',
    type: 'all', // all, patents, documents, authors
    categoryId: '',
    status: '',
    yearFrom: '',
    yearTo: '',
    author: '',
    sortBy: 'relevance'
  });

  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0
  });

  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const response = await categoriesAPI.getAll();
        setCategories(response.data.data || response.data);
      } catch (error) {
        console.error('Error fetching categories:', error);
      }
    };
    fetchCategories();
  }, []);

  const handleSearch = async (e) => {
    if (e) e.preventDefault();
    if (!filters.query.trim()) {
      toast.warning('Введіть пошуковий запит');
      return;
    }

    setLoading(true);
    try {
      const params = {
        q: filters.query,
        page: pagination.page,
        limit: pagination.limit,
        ...Object.fromEntries(
          Object.entries(filters).filter(([key, v]) => v !== '' && key !== 'query')
        )
      };

      const response = await searchAPI.search(params);
      setResults(response.data.results || { patents: [], documents: [], authors: [] });
      setPagination(prev => ({
        ...prev,
        total: response.data.total || 0
      }));
    } catch (error) {
      console.error('Error searching:', error);
      toast.error('Помилка пошуку');
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const clearFilters = () => {
    setFilters({
      query: filters.query,
      type: 'all',
      categoryId: '',
      status: '',
      yearFrom: '',
      yearTo: '',
      author: '',
      sortBy: 'relevance'
    });
  };

  const getResultsByTab = () => {
    switch (activeTab) {
      case 'patents':
        return results.patents || [];
      case 'documents':
        return results.documents || [];
      case 'authors':
        return results.authors || [];
      default:
        return [
          ...(results.patents || []).map(p => ({ ...p, _type: 'patent' })),
          ...(results.documents || []).map(d => ({ ...d, _type: 'document' })),
          ...(results.authors || []).map(a => ({ ...a, _type: 'author' }))
        ];
    }
  };

  const getTotalCount = () => {
    return (results.patents?.length || 0) + 
           (results.documents?.length || 0) + 
           (results.authors?.length || 0);
  };

  const currentYear = new Date().getFullYear();
  const years = Array.from({ length: 50 }, (_, i) => currentYear - i);

  return (
    <div className="search-page">
      <div className="container">
        <div className="search-header">
          <h1><FiSearch /> Розширений пошук</h1>
          <p>Пошук патентів, документів та авторів за різними критеріями</p>
        </div>

        {/* Форма пошуку */}
        <div className="search-form-section">
          <form onSubmit={handleSearch} className="main-search-form">
            <div className="search-input-wrapper">
              <FiSearch />
              <input
                type="text"
                name="query"
                placeholder="Введіть пошуковий запит..."
                value={filters.query}
                onChange={handleFilterChange}
              />
              {filters.query && (
                <button 
                  type="button" 
                  className="clear-input"
                  onClick={() => setFilters(prev => ({ ...prev, query: '' }))}
                >
                  <FiX />
                </button>
              )}
            </div>
            <button type="submit" className="btn btn-primary btn-lg">
              <FiSearch /> Пошук
            </button>
          </form>

          {/* Фільтри */}
          <div className="filters-panel">
            <div className="filters-header">
              <h3><FiFilter /> Фільтри</h3>
              <button type="button" className="btn btn-link" onClick={clearFilters}>
                Скинути
              </button>
            </div>

            <div className="filters-grid">
              <div className="filter-group">
                <label>Тип</label>
                <select name="type" value={filters.type} onChange={handleFilterChange}>
                  <option value="all">Всі типи</option>
                  <option value="patents">Тільки патенти</option>
                  <option value="documents">Тільки документи</option>
                  <option value="authors">Тільки автори</option>
                </select>
              </div>

              <div className="filter-group">
                <label>Категорія</label>
                <select name="categoryId" value={filters.categoryId} onChange={handleFilterChange}>
                  <option value="">Всі категорії</option>
                  {categories.map(cat => (
                    <option key={cat.id} value={cat.id}>{cat.name}</option>
                  ))}
                </select>
              </div>

              <div className="filter-group">
                <label>Статус патенту</label>
                <select name="status" value={filters.status} onChange={handleFilterChange}>
                  <option value="">Будь-який</option>
                  <option value="granted">Діючий</option>
                  <option value="pending">Очікує</option>
                  <option value="expired">Закінчився</option>
                  <option value="rejected">Відхилено</option>
                </select>
              </div>

              <div className="filter-group">
                <label>Рік від</label>
                <select name="yearFrom" value={filters.yearFrom} onChange={handleFilterChange}>
                  <option value="">Будь-який</option>
                  {years.map(year => (
                    <option key={year} value={year}>{year}</option>
                  ))}
                </select>
              </div>

              <div className="filter-group">
                <label>Рік до</label>
                <select name="yearTo" value={filters.yearTo} onChange={handleFilterChange}>
                  <option value="">Будь-який</option>
                  {years.map(year => (
                    <option key={year} value={year}>{year}</option>
                  ))}
                </select>
              </div>

              <div className="filter-group">
                <label>Сортування</label>
                <select name="sortBy" value={filters.sortBy} onChange={handleFilterChange}>
                  <option value="relevance">За релевантністю</option>
                  <option value="date_desc">Спочатку нові</option>
                  <option value="date_asc">Спочатку старі</option>
                  <option value="title">За назвою</option>
                </select>
              </div>
            </div>
          </div>
        </div>

        {/* Результати */}
        {loading ? (
          <Loading />
        ) : getTotalCount() > 0 ? (
          <div className="search-results">
            <div className="results-tabs">
              <button 
                className={`tab ${activeTab === 'all' ? 'active' : ''}`}
                onClick={() => setActiveTab('all')}
              >
                Всі ({getTotalCount()})
              </button>
              <button 
                className={`tab ${activeTab === 'patents' ? 'active' : ''}`}
                onClick={() => setActiveTab('patents')}
              >
                <FiAward /> Патенти ({results.patents?.length || 0})
              </button>
              <button 
                className={`tab ${activeTab === 'documents' ? 'active' : ''}`}
                onClick={() => setActiveTab('documents')}
              >
                <FiFileText /> Документи ({results.documents?.length || 0})
              </button>
              <button 
                className={`tab ${activeTab === 'authors' ? 'active' : ''}`}
                onClick={() => setActiveTab('authors')}
              >
                <FiUser /> Автори ({results.authors?.length || 0})
              </button>
            </div>

            <div className="results-list">
              {getResultsByTab().map((item, index) => (
                <ResultItem key={`${item._type || activeTab}-${item.id}-${index}`} item={item} type={item._type || activeTab} />
              ))}
            </div>

            {pagination.total > pagination.limit && (
              <Pagination
                currentPage={pagination.page}
                totalPages={Math.ceil(pagination.total / pagination.limit)}
                onPageChange={(page) => {
                  setPagination(prev => ({ ...prev, page }));
                  handleSearch();
                }}
              />
            )}
          </div>
        ) : filters.query && !loading ? (
          <div className="no-results">
            <FiSearch size={48} />
            <h3>Нічого не знайдено</h3>
            <p>Спробуйте змінити пошуковий запит або фільтри</p>
          </div>
        ) : (
          <div className="search-tips">
            <h3>Поради для пошуку</h3>
            <ul>
              <li>Використовуйте ключові слова з назви або опису</li>
              <li>Введіть номер патенту для точного пошуку</li>
              <li>Пошук за прізвищем автора</li>
              <li>Використовуйте фільтри для звуження результатів</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

const ResultItem = ({ item, type }) => {
  const getIcon = () => {
    switch (type) {
      case 'patent':
      case 'patents':
        return <FiAward />;
      case 'document':
      case 'documents':
        return <FiFileText />;
      case 'author':
      case 'authors':
        return <FiUser />;
      default:
        return <FiFileText />;
    }
  };

  const getLink = () => {
    switch (type) {
      case 'patent':
      case 'patents':
        return `/patents/${item.id}`;
      case 'document':
      case 'documents':
        return `/documents/${item.id}`;
      case 'author':
      case 'authors':
        return `/authors/${item.id}`;
      default:
        return '#';
    }
  };

  const getTypeLabel = () => {
    switch (type) {
      case 'patent':
      case 'patents':
        return 'Патент';
      case 'document':
      case 'documents':
        return 'Документ';
      case 'author':
      case 'authors':
        return 'Автор';
      default:
        return '';
    }
  };

  const getTitle = () => {
    if (type === 'author' || type === 'authors') {
      return `${item.lastName} ${item.firstName} ${item.middleName || ''}`;
    }
    return item.title;
  };

  const getSubtitle = () => {
    if (type === 'patent' || type === 'patents') {
      return item.number;
    }
    if (type === 'author' || type === 'authors') {
      return item.degree || item.position || '';
    }
    return item.docType || '';
  };

  return (
    <Link to={getLink()} className="result-item">
      <div className="result-icon">{getIcon()}</div>
      <div className="result-content">
        <span className="result-type">{getTypeLabel()}</span>
        <h4>{getTitle()}</h4>
        {getSubtitle() && <p className="result-subtitle">{getSubtitle()}</p>}
        {item.abstract && (
          <p className="result-abstract">
            {item.abstract.length > 200 ? `${item.abstract.substring(0, 200)}...` : item.abstract}
          </p>
        )}
      </div>
    </Link>
  );
};

export default Search;
